const e={title:"Aplicație Hartă de Călătorie Animată | Creator Video Evidențierea Călătoriei",description:"Transformă pozele tale în videoclipuri uimitoare de evidențiere a călătoriei cu aplicația noastră de hartă de călătorie animată care prezintă animatorul de rută de călătorie și animația rutei de călătorie. Creează videoclipuri de recapitulare a călătoriei și animații de rută de călătorie cu aplicația creator de povești de călătorie. Folosește aplicația de animație de călătorie pentru a transforma galeria ta foto în videoclipuri de hartă de călătorie animate. Confidențialitate mai întâi, funcționează complet offline în modul avion.",keywords:"aplicație hartă călătorie animată, aplicație creator video călătorie, aplicație animator rută călătorie, aplicație video evidențiere călătorie, aplicație video recapitulare călătorie, animație rută călătorie, aplicație animație călătorie, aplicație poveste călătorie, aplicație hartă călătorie, video călătorie automat, animație traseu zbor, aplicație călătorie gratuită, creator video offline, video călătorie estetice, aplicație călătorie confidențială"},i={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Cum Funcționează",video:"Video",features:"Funcționalități",theApp:"Aplicația"},a={badge:"Transformă Pozele în Povești de Călătorie",title1:"Galeria Ta Foto,",title2:"În Prim-Plan",description:"TripReel creează automat videoclipuri estetice de călătorie pe baza locațiilor pozelor tale. Urmărește cum călătoriile tale prind viață cu hărți animate și trasee de zbor pe un glob 3D, în timp ce datele tale rămân private și sigure",secure:"100% Sigur",worksOffline:"Funcționează Offline",globeAlt:"Animație Glob TripReel"},t={title:"Cum Funcționează",subtitle:"Trei pași simpli pentru a crea videoclipul tău perfect",step1:{title:"Acordă Acces la Poze",description:"Permite TripReel să acceseze galeria foto. Aplicația citește doar metadatele de locație, nimic altceva."},step2:{title:"Detectare Automată a Călătoriilor",description:"TripReel analizează metadatele de locație și identifică inteligent călătoriile tale în funcție de date și locații."},step3:{title:"Generează Videoclipul",description:"Privește cum animatorul nostru de rută de călătorie creează o animație estetică pe glob a călătoriei tale, gata să fie partajată pe rețelele sociale."}},r={title:"Vezi Magia în Acțiune",subtitle:"Descoperă cum aplicația noastră de hartă de călătorie animată transformă galeria ta foto în videoclipuri uimitoare de evidențiere a călătoriei folosind animații avansate de rută de călătorie",caption:"Așa va arăta videoclipul tău final de călătorie creat cu animatorul nostru de rută de călătorie"},l={title:"Tot Ce Ai Nevoie",subtitle:"Funcționalități puternice proiectate pentru călătorii moderni",twoTap:{title:"Video în Două Atingeri",description:"Creează videoclipuri uimitoare de evidențierea călătoriei din galeria foto în doar două atingeri folosind aplicația noastră de animație de călătorie. Fără editare necesară."},smartTrip:{title:"Detectare Inteligentă",description:"Aplicația de hartă de călătorie animată găsește și grupează automat călătoriile tale analizând datele și metadatele de locație din poze."},globe:{title:"Animație estetică pe Glob",description:"Privește cum călătoria ta prinde viață cu un glob 3D uimitor care arată rutele tale animate și traseele de zbor din întreaga lume cu aplicația noastră de animator de rută de călătorie."},privacy:{title:"Confidențialitate Mai Întâi",description:"Aplicația de creator video de călătorie procesează totul pe dispozitivul tău. Pozele tale nu părăsesc niciodată telefonul. Funcționează în modul avion."},customStyles:{title:"Stiluri Personalizabile",description:"Alege dintre mai multe stiluri de glob și personalizări în aplicația de animație de călătorie pentru a se potrivi esteticii tale și a face fiecare video unic."},manualControl:{title:"Control Manual",description:"Aplicația de povești de călătorie îți permite să adaugi manual călătorii noi dacă serviciile de locație nu erau activate pe dispozitiv."}},o={title:"Idei Creative de Video",subtitle:"Inspiră-te cu ceea ce poți crea folosind aplicația noastră de hartă de călătorie animată. De la scurte călătorii de weekend până la aventuri de un an, creează videoclipuri uimitoare pentru fiecare călătorie folosind animatorul de rută de călătorie.",description:"Fie că creezi o animație de hartă de călătorie, documentezi o rută de zbor sau faci o recapitulare anuală de călătorii, aplicația creator de povești de călătorie face ușor să transformi amintirile tale în videoclipuri care pot fi partajate.",ideas:{yearRecap:{title:"Recapitulare 2025",description:"Creează automat videoclipul cu animațiile rutelor de călătorie din 2025 folosind aplicația de video recapitulare călătorie"},europeRoadTrip:{title:"Tur Europa cu Mașina",description:"Prezintă aventura ta europeană cu hărți de rută animate folosind aplicația de hartă de călătorie animată"},southeastAsia:{title:"Călătorie Asia de Sud-Est",description:"Vizualizează traseul tău prin mai multe țări cu aplicația de animație de călătorie"},japanRail:{title:"Călătorie Tren în Japonia",description:"Creează video-uri de evidențiere a călătoriei cu rutele tale de tren prin Japonia cu animatorul de rută de călătorie"},crossCountry:{title:"Traversare SUA",description:"Transformă turul tău american într-un video epic de rută folosind aplicația de animator de rută de călătorie"},islandHopping:{title:"Tururi pe Insule",description:"Arată călătoriile tale din insulă în insulă cu animații 3D uimitoare cu aplicația de hartă de călătorie animată"},worldTour:{title:"Tur Mondial Montaj",description:"Combină mai multe călătorii într-un singur videoclip global uimitor de recapitulare a călătoriei cu aplicația noastră de povești de călătorie"},travelPlans:{title:"Planuri de Călătorie 2026",description:"Vizualizează și planuiește aventurile tale din 2026 cu aplicația de animație de călătorie"},lifetimeTravel:{title:"Poveste de Călătorie",description:"Creează un videoclip cu toate călătoriile tale din viață folosind aplicația de creator video de călătorie"},regionalExplorer:{title:"Explorator Regional",description:"Trasează aventurile tale prin state, provincii și regiuni cu animatorul de rută de călătorie"},festivalCircuit:{title:"Circuit de Festivaluri",description:"Mapează călătoria ta prin festivaluri de muzică și evenimente folosind aplicația de hartă de călătorie animată"},bikeRoutes:{title:"City Break-urile Mele",description:"Prezintă toate escapadele tale urbane cu aplicația de video evidențiere călătorie"}}},c={title:"Aplicația",subtitle:"Disponibilă acum pe App Store",alt1:"Aplicație Video Recapitulare Călătorie - Creează video-uri uimitoare în câteva secunde",alt2:"Aplicație Hartă de Călătorie Animată - Folosește metadatele pozelor tale",alt3:"Aplicație Detectare Călătorii - Grupează automat călătoriile tale",alt4:"Aplicație Animator Rută Călătorie - Animație glob a călătoriei tale",alt5:"Aplicație Animație Călătorie - Personalizează video-urile tale de călătorie"},n={comingSoon:"În Curând",androidTitle:"Aplicația Android În Curând!",androidMessage:'Versiunea Android nu este încă disponibilă, dar va fi în curând. Trimite-mi un mesaj la <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> și te voi anunța când va fi gata!',gotIt:"Am înțeles!"},d={title:"Întrebări Frecvente",subtitle:"Tot ce trebuie să știi despre TripReel",q1:{question:"Pot folosi această aplicație de hartă de călătorie animată complet offline în modul avion?",answer:"Da! Pentru utilizatorii premium, aplicația de video evidențiere călătorie poate fi folosită complet offline în modul avion fără limitări. Pentru utilizatorii non-premium, unele funcționalități sunt susținute de reclame care ar putea necesita activarea temporară a internetului, dar utilizatorii premium pot crea videoclipuri de recapitulare a călătoriei complet offline fără reclame."},q2:{question:"Cum pot elimina watermark-ul din videoclipurile mele de animație de călătorie?",answer:"Mulți oameni întreabă ce aplicație creator video de călătorie a fost folosită pentru a crea aceste video-uri de hartă de călătorie animate. După upgrade la premium, ai opțiunea de a adăuga o versiune mai mică a watermark-ului (doar cu numele aplicației) sau să îl elimini complet din videoclipurile tale de evidențiere a călătoriei dacă dorești."},q3:{question:"Sunt datele mele foto sigure și private în această aplicație animator de rută de călătorie?",answer:"Absolut! Aplicația de hartă de călătorie animată citește doar metadatele de locație din pozele tale - nu accesăm, stocăm sau transmitem niciodată conținutul real al pozelor. Toată procesarea videoclipurilor de animație de călătorie se întâmplă local pe dispozitivul tău, și nicio dată nu părăsește telefonul tău. Poți verifica acest lucru creând videoclipuri de recapitulare a călătoriei în modul avion - funcționează perfect offline!"},q4:{question:"Ce fac dacă pozele mele nu au date de locație pentru animația rutei de călătorie?",answer:"Nicio problemă! Dacă serviciile de locație nu erau activate când ai făcut pozele, aplicația creator de povești de călătorie îți permite să creezi călătorii manual și să adaugi locații singur. Animatorul de rută de călătorie îți oferă control complet pentru a personaliza cronologia călătoriilor tale și a crea videoclipuri frumoase de hartă de călătorie animată chiar și fără date GPS."},q5:{question:"Cum detectează această aplicație de recapitulare a călătoriei călătoriile mele automat?",answer:"Aplicația de hartă de călătorie animată analizează metadatele de locație și marcajele de timp din pozele tale pentru a identifica inteligent când și unde ai călătorit. Grupează locațiile și datele apropiate pentru a detecta automat călătoriile tale și a crea incredibile videoclipuri de evidențiere a călătoriei fără nicio muncă manuală."},q6:{question:"Pot personaliza aspectul videoclipurilor mele de evidențiere a călătoriei?",answer:"Da! Aplicația noastră de animație de călătorie îți permite să alegi dintre mai multe stiluri de glob și să personalizezi diverse aspecte ale videoclipurilor tale de hartă de călătorie animată pentru a se potrivi esteticii tale personale. Utilizatorii premium au acces la stiluri suplimentare de animație a rutelor, teme de hartă și opțiuni de trasee de zbor."},q7:{question:"Trebuie să creez un cont pentru a folosi această aplicație creator video de călătorie?",answer:"Nu este necesar niciun cont! Aplicația de animație de călătorie funcționează imediat după descărcare. Nu există înregistrare, nu există autentificare și nu sunt necesare informații personale. Doar descarcă aplicația de hartă de călătorie animată și începe să creezi videoclipurile tale cu rute de călătorie animate imediat."},q8:{question:"De ce lipsește o locație din videoclipul meu de hartă de călătorie animată?",answer:"Aplicația de animator de rută de călătorie poate funcționa doar cu datele disponibile, așa că ai nevoie de cel puțin câteva poze în acea locație cu date GPS. Asigură-te că aveai serviciile de locație activate când erai acolo. Uneori recepția GPS slabă poate cauza date de locație greșite. Dacă locația ta încă nu apare în videoclipul tău de evidențiere a călătoriei, poți adăuga manual acea locație din Trips Overview > butonul Edit. Te rog folosește Contact pentru a raporta problema."},q9:{question:"Unde pot partaja videoclipurile mele de recapitulare a călătoriei și animațiile rutelor de călătorie?",answer:"Poți partaja videoclipurile tale de animație de călătorie pe toate platformele sociale! Aplicația noastră de hartă de călătorie animată permite diferite rapoarte de aspect (vertical, widescreen, cinema, pătrat) pentru videoclipurile tale de hartă de călătorie animate pentru a se potrivi mai bine fiecărei platforme - perfect pentru Instagram, TikTok, YouTube, Facebook și altele."},q10:{question:"Unde pot raporta un bug?",answer:"Doar contactează-mă direct la marian@qod.ee, explicând pe scurt care este problema."}},u={title:"Suport Email",description:"Dacă ai orice feedback sau întâmpini probleme, te rog să mă contactezi direct la acest email și voi citi și gestiona personal cererea ta cât mai repede posibil. Mulțumesc că folosești aplicația!",close:"Închide"},p={default:{title:"🍪 Cookie-uri",message:"Folosim cookie-uri pe site-ul TripReel pentru a îmbunătăți experiența ta. Nu sunt colectate date personale.",accept:"Acceptă",decline:"Refuză",details:"Detalii"},theme:{title:"🍪 Cookie-uri",message:"🌙 Pentru a salva preferința ta de temă, trebuie să accepți cookie-urile esențiale pe site-ul TripReel. Fără ele, alegerea ta de temă nu poate fi salvată.",accept:"Acceptă",decline:"Refuză",details:"Detalii"}},s={privacy:"Politica de Confidențialitate",cookies:"Politica de Cookie-uri Site",contact:"Contact",cookiePreferences:"Preferințe Cookie-uri",madeWith:"Creat cu",forTravelers:"pentru călătorii din întreaga lume",copyright:"© {{year}} TripReel."},m={title:"Gata să Împărtășești Călătoria Ta?",description:"Descarcă TripReel astăzi și transformă galeria foto în videoclipuri frumoase de evidențiere a călătoriei cu aplicația noastră de hartă de călătorie animată care prezintă animatorul de rută de călătorie și animația rutei de călătorie. Aventurile tale merită să fie celebrate cu incredibile videoclipuri de recapitulare a călătoriei.",features:"Gratuit de descărcat • Rapid & Convenabil • Confidențialitate garantată"},v={title:"Despre TripReel",subtitle:"Creator profesional de videoclipuri de evidențiere a călătoriei și aplicație animator de rută de călătorie",howItWorks:{title:"Cum funcționează aplicația noastră de recapitulare a călătoriei",description:"Aplicația de animație de călătorie folosește algoritmi inteligenți pentru a scana datele GPS din pozele tale și a detecta automat călătoriile tale. Animatorul de rută de călătorie apoi creează animații cinematice și fluide ale rutei de călătorie arătând drumul tău prin orașe, țări și continente. Fie că creezi un videoclip rapid de evidențiere a călătoriei de weekend sau un videoclip de recapitulare a călătoriei de un an, aplicația de hartă de călătorie animată face totul fără efort."},customization:{title:"Personalizare extinsă pentru videoclipurile tale de animație de călătorie",description:"Aplicația creator de povești de călătorie oferă opțiuni de personalizare de nivel profesional pentru a face videoclipurile tale de hartă de călătorie animată cu adevărat unice:",features:{videoQuality:"Alege între 30 FPS, 60 FPS sau premium 90 FPS pentru animații de rută de călătorie fluide ca mătase în videoclipurile tale de evidențiere a călătoriei",bitrate:"Ajustează calitatea videoclipului (bitrate) de la normal la înaltă pentru videoclipuri de hartă de călătorie cristaline fără artefacte vizuale",earthStyles:"Selectează între mai multe stiluri de glob impresionante incluzând Realist, Lumini Nocturne, Hartă de Zi și vederi din Satelit pentru videoclipurile tale de hartă de călătorie animată",borders:"Activează frontierele țărilor în animatorul tău de rută de călătorie cu culori și grosime personalizabile pentru vizualizare geografică îmbunătățită",aspectRatios:"Creează videoclipuri de animație de călătorie în formate Vertical (9:16), Widescreen (16:9), Cinema (2.35:1) sau Pătrat (1:1) perfecte pentru Instagram, TikTok, YouTube și alte platforme sociale",tripSpeed:"Controlează viteza animatorului de rută de călătorie între locații (până la 3500 km/s) pentru a crea videoclipuri de recapitulare a călătoriei dinamice sau relaxate",pauseDuration:"Ajustează durata pauzei în fiecare locație (0.5-5 secunde) pentru a evidenzia destinații importante în videoclipurile tale de evidențiere a călătoriei",locationLabels:"Afișează etichete de Oraș, Regiune și/sau Țară în videoclipurile tale de hartă de călătorie animată pentru a oferi context călătoriei tale",pathDisplay:"Activează dacă dorești să afișezi toate căile călătoriilor trecute sau doar călătoria curentă în animația ta de rută de călătorie"}}},f={meta:e,header:i,hero:a,howItWorks:t,videoSection:r,features:l,videoIdeas:o,screenshots:c,appStore:n,faq:d,contact:u,cookieBanner:p,footer:s,cta:m,about:v};export{v as about,n as appStore,u as contact,p as cookieBanner,m as cta,f as default,d as faq,l as features,s as footer,i as header,a as hero,t as howItWorks,e as meta,c as screenshots,o as videoIdeas,r as videoSection};
